import type {
  CountTokensParameters,
  CountTokensResponse,
  EmbedContentParameters,
  EmbedContentResponse,
  GenerateContentParameters,
  GenerateContentResponse,
} from '@google/genai';
import type { UserTierId, GeminiUserTier } from '../code_assist/types.js';
import type { ContentGenerator } from './contentGenerator.js';
import type { LlmRole } from '../telemetry/llmRole.js';

const MODELS_PREFIX = 'models/';

/**
 * A {@link ContentGenerator} decorator that translates model names before
 * delegating to the wrapped generator.
 *
 * Some backends expect a different model name than the one used throughout the
 * CLI (e.g. Google account auth backends do not recognize the string
 * `gemini-3.5-flash` and expect `gemini-3-flash` instead). This wrapper maps
 * the requested model name using the provided dictionary, preserving any
 * `models/` prefix.
 */
export class ModelMappingContentGenerator implements ContentGenerator {
  constructor(
    private readonly wrapped: ContentGenerator,
    private readonly mappings: Record<string, string>,
  ) {}

  /**
   * Returns the wrapped {@link ContentGenerator}.
   */
  getWrapped(): ContentGenerator {
    return this.wrapped;
  }

  private mapModel(model: string | undefined): string | undefined {
    if (model === undefined) {
      return model;
    }

    const hasPrefix = model.startsWith(MODELS_PREFIX);
    const bareModel = hasPrefix ? model.slice(MODELS_PREFIX.length) : model;
    const mapped = this.mappings[bareModel];
    if (mapped === undefined) {
      return model;
    }
    return hasPrefix ? `${MODELS_PREFIX}${mapped}` : mapped;
  }

  async generateContent(
    request: GenerateContentParameters,
    userPromptId: string,
    role: LlmRole,
  ): Promise<GenerateContentResponse> {
    const mappedRequest: GenerateContentParameters = {
      ...request,
      model: this.mapModel(request.model) ?? request.model,
    };
    return this.wrapped.generateContent(mappedRequest, userPromptId, role);
  }

  async generateContentStream(
    request: GenerateContentParameters,
    userPromptId: string,
    role: LlmRole,
  ): Promise<AsyncGenerator<GenerateContentResponse>> {
    const mappedRequest: GenerateContentParameters = {
      ...request,
      model: this.mapModel(request.model) ?? request.model,
    };
    return this.wrapped.generateContentStream(
      mappedRequest,
      userPromptId,
      role,
    );
  }

  async countTokens(
    request: CountTokensParameters,
  ): Promise<CountTokensResponse> {
    const mappedRequest: CountTokensParameters = {
      ...request,
      model: this.mapModel(request.model) ?? request.model,
    };
    return this.wrapped.countTokens(mappedRequest);
  }

  async embedContent(
    request: EmbedContentParameters,
  ): Promise<EmbedContentResponse> {
    const mappedRequest: EmbedContentParameters = {
      ...request,
      model: this.mapModel(request.model) ?? request.model,
    };
    return this.wrapped.embedContent(mappedRequest);
  }

  get userTier(): UserTierId | undefined {
    return this.wrapped.userTier;
  }

  get userTierName(): string | undefined {
    return this.wrapped.userTierName;
  }

  get paidTier(): GeminiUserTier | undefined {
    return this.wrapped.paidTier;
  }
}
